Given two matrices mat1[][] of size n × m and mat2[][] of size m × q, find their matrix product, where the resulting matrix has dimensions n × qExamples:Input: mat1[][] = [[1, 2, 3],                                 [4, 5, 6]],                                  mat2[][] = [[7, 8],                                [9, 10],                                [11, 12]]Output: [[58, 64],               [139, 154]]Explanation: Matrix mat1[ ][ ] (2×3) is multiplied with Matrix mat2[ ][ ] (3×2) by computing the dot product of a's rows with b's columns. This results in a new matrix of size 2×2 containing the summed products for each position.Input: mat1[][] = [[17, 4],                                [17, 16]],                      mat2[][] = [9, 2],                               [7, 1]]Output: [[181, 38],               [265, 50]]Explanation: Matrix mat1[ ][ ] (2×2) is multiplied with Matrix mat2[ ][ ] (2×2) by computing the dot product of a's rows with b's columns. This results in a new matrix of size 2×2 containing the summed products for each position.Try It YourselfTable of Content[Approach 1] - Using Nested Loops - O(n * m * q) Time and O(n * q) Space[Approach 2] - Using Divide and Conquer - O(n * m * q) Time and O(n * q) Space[Approach 3] - Using Strassen's Method[Approach 1] - Using Nested Loops - O(n * m * q) Time and O(n * q) SpaceThe main idea is to initializes the result matrix with zeros and fills each cell by computing the dot product of the corresponding row from a and column from . This is done using three nested loops: the outer two iterate over the result matrix cells, and the innermost loop performs the multiplication and addition.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<vector<int>> multiply(vector<vector<int>> &mat1, 
                                        vector<vector<int>> &mat2) {

    int n = mat1.size(), m = mat1[0].size(), 
                                    q = mat2[0].size();        

    // Initialize the result matrix with 
    // dimensions n×q, filled with 0s
    vector<vector<int>> res(n, vector<int>(q, 0));

    // Loop through each row of mat1
    for (int i = 0; i < n; i++) {

        // Loop through each column of mat2
        for (int j = 0; j < q; j++) {

            // Compute the dot product of 
            // row mat1[i] and column mat2[][j]
            for (int k = 0; k < m; k++) {
                res[i][j] += mat1[i][k] * mat2[k][j];
            }
        }
    }

    return res;
}

int main() {
    vector<vector<int>> mat1 = {
        {1, 2, 3},
        {4, 5, 6}
    }; 

    vector<vector<int>> mat2 = {
        {7, 8},
        {9, 10},
        {11, 12}
    };

    vector<vector<int>> res = multiply(mat1, mat2); 

    // Print the resulting matrix
    for (int i = 0; i < res.size(); i++) {
        for (int j = 0; j < res[i].size(); j++) {
            cout << res[i][j] << " ";
        }
        cout << endl;
    }

    return 0;
}


